=== FILE: rr_arbiter_props.sv ===
// Formal properties for rr_arbiter, written from interface_spec.md.
// Each assertion is an interface property tagged with the spec rule it checks.
module rr_arbiter_props (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk  (clk),
        .rst_n(rst_n),
        .req  (req),
        .grant(grant),
        .last (last)
    );

    // First-cycle flag guarding every $past and every post-reset property.
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Environment: the block is reset in the first cycle (last has no
    // initial value; the spec defines state from reset, RR-RESET).
    always @(*)
        if (!f_past_valid)
            assume (!rst_n);

    // Spec model of the priority order: last+1, last+2, last (mod 3).
    wire [1:0] f_p1 = (last == 2'd0) ? 2'd1 : (last == 2'd1) ? 2'd2 : 2'd0;
    wire [1:0] f_p2 = (last == 2'd0) ? 2'd2 : (last == 2'd1) ? 2'd0 : 2'd1;
    wire [1:0] f_p3 = last;
    wire [2:0] f_expect = req[f_p1] ? (3'b001 << f_p1) :
                          req[f_p2] ? (3'b001 << f_p2) :
                          req[f_p3] ? (3'b001 << f_p3) : 3'b000;

    // Wait counters for RR-BOUND: consecutive edges at which requester i
    // holds req high and is not granted. Cleared by reset, a grant, or a
    // dropped request.
    reg [1:0] f_wait0 = 2'd0;
    reg [1:0] f_wait1 = 2'd0;
    reg [1:0] f_wait2 = 2'd0;

    always @(posedge clk) begin
        if (!rst_n)
            f_wait0 <= 2'd0;
        else if (req[0] && !grant[0])
            f_wait0 <= (f_wait0 == 2'd3) ? 2'd3 : f_wait0 + 2'd1;
        else
            f_wait0 <= 2'd0;
    end

    always @(posedge clk) begin
        if (!rst_n)
            f_wait1 <= 2'd0;
        else if (req[1] && !grant[1])
            f_wait1 <= (f_wait1 == 2'd3) ? 2'd3 : f_wait1 + 2'd1;
        else
            f_wait1 <= 2'd0;
    end

    always @(posedge clk) begin
        if (!rst_n)
            f_wait2 <= 2'd0;
        else if (req[2] && !grant[2])
            f_wait2 <= (f_wait2 == 2'd3) ? 2'd3 : f_wait2 + 2'd1;
        else
            f_wait2 <= 2'd0;
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            // Helper invariant: last is 0, 1 or 2 (spec section 1).
            assert (last != 2'd3);

            // Grant lines: at most one bit high (spec section 1).
            assert ((grant & (grant - 3'b001)) == 3'b000);

            // RR-ONLY-REQUESTERS
            assert ((grant & ~req) == 3'b000);

            // RR-IDLE
            if (req == 3'b000)
                assert (grant == 3'b000);

            // RR-PICK: exactly one grant, the first requester in priority order.
            if (req != 3'b000)
                assert (grant != 3'b000);
            if (req != 3'b000)
                assert (grant == f_expect);

            // RR-RESET
            if (!$past(rst_n))
                assert (last == 2'd2);

            // RR-ROTATE
            if ($past(rst_n) && ($past(grant) != 3'b000))
                assert ((3'b001 << last) == $past(grant));

            // RR-HOLD
            if ($past(rst_n) && ($past(grant) == 3'b000))
                assert (last == $past(last));

            // RR-YIELD, one assertion per requester
            if ($past(rst_n) && $past(grant[0]) && ((req & 3'b110) != 3'b000))
                assert (!grant[0]);
            if ($past(rst_n) && $past(grant[1]) && ((req & 3'b101) != 3'b000))
                assert (!grant[1]);
            if ($past(rst_n) && $past(grant[2]) && ((req & 3'b011) != 3'b000))
                assert (!grant[2]);

            // RR-BOUND: helper bounds and the bound itself, per requester.
            assert (f_wait0 <= 2'd2);
            assert (f_wait1 <= 2'd2);
            assert (f_wait2 <= 2'd2);
            if (req[0] && !grant[0])
                assert (f_wait0 < 2'd2);
            if (req[1] && !grant[1])
                assert (f_wait1 < 2'd2);
            if (req[2] && !grant[2])
                assert (f_wait2 < 2'd2);
        end
    end

    // Covers: scenarios the proof must still allow (vacuity checks).
    always @(posedge clk) begin
        if (f_past_valid) begin
            cover (req == 3'b000);
            cover ((req == 3'b111) && (last == 2'd0));
            cover ((req == 3'b111) && (last == 2'd1));
            cover ((req == 3'b111) && (last == 2'd2));
            cover (grant == 3'b001);
            cover (grant == 3'b010);
            cover (grant == 3'b100);
            cover ($past(rst_n) && ($past(grant) == 3'b000) && (last != 2'd2));
            cover ($past(rst_n) && $past(grant[0]) && ((req & 3'b110) != 3'b000));
            cover ($past(rst_n) && $past(grant[1]) && ((req & 3'b101) != 3'b000));
            cover ($past(rst_n) && $past(grant[2]) && ((req & 3'b011) != 3'b000));
            cover ((f_wait0 == 2'd2) && req[0]);
            cover ((f_wait1 == 2'd2) && req[1]);
            cover ((f_wait2 == 2'd2) && req[2]);
            cover ($past(f_past_valid) && !$past(rst_n) && $past(last) != 2'd2);
        end
    end
endmodule
=== END FILE ===
